def escape(s: t.Any, /) -> Markup:
    """Replace the characters &, <, >, ', and " in the string with HTML-safe sequences."""
    if type(s) is str:
        return Markup(_escape_inner(s))
    if hasattr(s, "__html__"):
        return Markup(s.__html__())
    return Markup(_escape_inner(str(s)))

def soft_str(s: t.Any, /) -> str:
    """Convert an object to a string if it isn't already. This preserves a Markup string."""
    if not isinstance(s, str):
        return str(s)
    return s

def unescape(self, /) -> str:
    """Convert HTML entities with the characters they represent."""
    from html import unescape
    return unescape(str(self))
